sys_script_include.script:
var BNBCertificateMangementUtils = Class.create();
BNBCertificateMangementUtils.prototype = {
	initialize: function () {
	},

	updatedAllCertsMetadata: function () {
		try {
			var grandTotal = { read: 0, absent: 0, remote: 0 };
			var determineScopeAndMetadata = this.determineScopeAndMetadata;
			var certGR = new GlideRecord("cmdb_ci_certificate");
			certGR.addQuery('install_status', '!=', 100);
			grandTotal.read += 1;
			grandTotal.remote += 1;
			determineScopeAndMetadata(certGR);
			return grandTotal;
		} catch (ex) {
			throw new Error("EDX Failed to process updateCertificateInstallStatus " + ex);
		}
	},

	determineScopeAndMetadata: function (cert) {
		try {
			var now = new GlideDateTime();
			var daysBeforeExpiry = parseInt(gs.getProperty("glide.discovery.certs.days_before_expiration_to_create_renewal_task", "60"));

			var updatedFields = {
				u_ca_scope: BNBCertificateMangementUtils.getCAScopeFromCN(cert.subject_common_name),
				renewal_tracking: 'none'
			};

			var updatedMetadata = {
				"certificate": cert.sys_id,
				"auto_renew_days_before_expiry": daysBeforeExpiry,
				"auto_renew_enabled": false,
				"auto_renewal_state": "ready"
			};

			if (!cert.issuer_common_name || (cert.issuer_common_name == cert.subject_common_name)) {
				cert.u_ca_scope = null;
			} else if (cert.issuer_common_name.getDisplayValue().toLowerCase().startsWith("banco do nordeste")) {
				cert.u_ca_scope = "internal";
			}

			if (cert.u_ca_scope) {
				if (cert.u_ca_scope == 'external') {
					cert.renewal_tracking = 'priority1';
					updatedMetadata.auto_renew_enabled = true;
				} else {
					if (!(cert.is_self_signed || cert.is_ca) && cert.root_issuer != cert.sys_id) {
						cert.renewal_tracking = 'priority3';
						updatedMetadata.auto_renew_enabled = true;
					} else {
						cert.renewal_tracking = 'none';
						cert.u_ca_scope = null;
					}
				}

			}
			// Atualiza os campos no certificado (CA Scope e prioridade de renovação)
			cert.update();
			cert.service_type = cert.u_ca_scope;
			cert.update();
			if (new global.GlideQuery("sn_disco_certmgmt_certificate_metadata")
				.where("certificate", cert.sys_id)
				.count() > 0) {
				metadataUpdate = 'Updated';
				var upd = new global.GlideQuery("sn_disco_certmgmt_certificate_metadata")
					.where("certificate", cert.sys_id)
					.updateMultiple(updatedMetadata);
			} else {
				if (updatedMetadata.auto_renew_enabled) {
					metadataUpdate = 'Inserted';
					new global.GlideQuery("sn_disco_certmgmt_certificate_metadata")
						.insert(updatedMetadata);
				}
			}
			return "Certificate:" + cert.subject_common_name +
				" Scope:" + cert.u_ca_scope +
				" Renewal Tracking:" + cert.renewal_tracking +
				" Metadata Record:" + metadataUpdate +
				" Auto Renew Enabled:" + updatedMetadata.auto_renew_enabled +
				" Days before expiry:" + updatedMetadata.auto_renew_days_before_expiry;
		} catch (ex) {
			gs.error("EDX Failed to process Certificate " + cert.getDisplayValue() + ' Error:' + ex, "error");
			return "Error " + ex;
		}
	},

	type: 'BNBCertificateMangementUtils'
};

BNBCertificateMangementUtils.getCAScopeFromCN = function (commonName) {
	if (commonName.endsWith('bnb.gov.br')) {
		return 'external';
	} else {
		if (commonName.endsWith('intra.bnb') ||
			commonName.endsWith('dmz.bnb') ||
			commonName.endsWith('dreads.bnb')) {
			return 'internal';
		}
	}
	return null;
};
